import pandas as pd, numpy as np, json, math
x=pd.read_csv(\"respondents.csv\")
cb=json.load(open(\"codebook.json\"))
valid={v[\"name\"]:v[\"valid_values\"] for v in cb[\"variables\"] if \"valid_values\" in v}
def base(d):
 w=d.weight_base
 return {\"n\":len(d),\"wN\":round(w.sum(),3),\"ess\":round(w.sum()**2/(w*w).sum(),3) if len(d) else 0}
def mean(d,v): return np.average(d[v],weights=d.weight_base)
def dist(d,v):
 q=d[d[v].isin(valid[v])]
 r={\"eligible\":base(d),\"valid\":base(q),\"numeric_missing\":int(d[v].isin([97,98,99]).sum()),\"blank\":int(d[v].isna().sum())}
 if len(q)>=40:r[\"pct\"]={str(k):round(100*np.average(q[v]==k,weights=q.weight_base),3) for k in valid[v]}
 return r
def calc(d,k):
 a=k+\"_pre\"; b=k+\"_post\"; q=d[d[a].isin(valid[a])&d[b].isin(valid[b])&(d.followup_status==1)].copy()
 pre=(q[a]>=4).astype(float) if k==\"consideration\" else q[a]
 post=(q[b]>=4).astype(float) if k==\"consideration\" else q[b]
 w=q.weight_base; D=post-pre; mu=np.average(D,weights=w)
 V=len(q)/(len(q)-1)*np.sum(w*w*(D-mu)**2)/w.sum()**2
 out={\"eligible\":base(d),\"pair\":base(q)}
 if len(q)>=40:out.update(pre=round(np.average(pre,weights=w)*100,3),post=round(np.average(post,weights=w)*100,3),change=round(mu*100,3))
 return out,mu,V,q
def inf(e,v):
 se=math.sqrt(v); p=math.erfc(abs(e/se)/math.sqrt(2)) if se else 1
 return {\"contrast_pp\":round(e*100,4),\"se_pp\":round(se*100,4),\"ci95_pp\":[round((e-1.959963984540054*se)*100,4),round((e+1.959963984540054*se)*100,4)],\"p\":p}
def holm(rs):
 order=sorted(range(len(rs)),key=lambda i:rs[i][\"p\"]); mx=0
 for rank,i in enumerate(order):
  mx=max(mx,(len(rs)-rank)*rs[i][\"p\"]); rs[i][\"p_holm\"]=min(1,mx)
out={\"primary\":{},\"children\":{},\"waves\":{},\"paired_distributions\":{},\"attrition\":{}}
ps=[]; hs=[]
for k in [\"awareness\",\"consideration\",\"usage\"]:
 cs=[calc(x[x.assignment==z],k) for z in [0,1]]
 r=inf(cs[1][1]-cs[0][1],cs[0][2]+cs[1][2]);ps.append(r)
 out[\"primary\"][k]={\"control\":cs[0][0],\"invitation\":cs[1][0],\"inference\":r}
 out[\"paired_distributions\"][k]={str(z):{t:dist(cs[z][3],k+\"_\"+t) for t in [\"pre\",\"post\"]} for z in [0,1]}
 out[\"waves\"][k]={str(z):{t:dist(x[(x.assignment==z)&((x.followup_status==1) if t==\"post\" else True)],k+\"_\"+t) for t in [\"pre\",\"post\"]} for z in [0,1]}
 cells=[[calc(x[(x.assignment==z)&(x.children_under18==c)],k) for z in [0,1]] for c in [0,1]]
 eff=[q[1][1]-q[0][1] for q in cells]
