out[\"selection\"]={}
for v in [\"awareness_pre\",\"consideration_pre\",\"usage_pre\",\"children_under18\",\"digital_confidence_pre\",\"budget_pressure_pre\"]:
 out[\"selection\"][v]={str(f):dist(x[x.followup_status==f],v) for f in [0,1]}
out[\"balance\"]={}
for subset,d in [(\"baseline\",x),(\"returners\",x[x.followup_status==1])]:
 out[\"balance\"][subset]={v:{str(z):dist(d[d.assignment==z],v) for z in [0,1]} for v in [\"children_under18\",\"digital_confidence_pre\",\"budget_pressure_pre\"]}
q=calc(x,\"consideration\")[3]
out[\"observational\"]={}
for v in [\"receipt_log\",\"recall_post\"]:
 out[\"observational\"][v]={}
 for g in [0,1]:
  d=q[q[v]==g]; out[\"observational\"][v][str(g)]={\"base\":base(d),\"pre_top2\":round(np.average(d.consideration_pre>=4,weights=d.weight_base)*100,3),\"post_top2\":round(np.average(d.consideration_post>=4,weights=d.weight_base)*100,3)}
out[\"concordance\"]={str(g):dist(x[(x.followup_status==1)&(x.receipt_log==g)],\"recall_post\") for g in [0,1]}
out[\"diagnostics\"]={v:dist(x[(x.followup_status==1)&(x.recall_post==1)],v) for v in [\"campaign_clear_post\",\"campaign_relevant_post\",\"campaign_trust_post\",\"campaign_channel_post\"]}
out[\"correlations\"]={}
vs=[\"campaign_clear_post\",\"campaign_relevant_post\",\"campaign_trust_post\"]
for i,a in enumerate(vs):
 for b in vs[i+1:]:
  d=x[(x.recall_post==1)&x[a].isin(valid[a])&x[b].isin(valid[b])]
  w=d.weight_base; A=d[a]-mean(d,a);B=d[b]-mean(d,b)
