out[\"needs\"]={str(c):dist(x[x.children_under18==c],\"meal_stress_pre\") for c in [0,1]}
out[\"experience\"]={v:dist(x[(x.followup_status==1)&(x.usage_post==1)],v) for v in [\"usage_days_post\",\"satisfaction_post\"]}
out[\"other_distributions\"]={v:dist(x[x.followup_status==1],v) for v in [\"meal_stress_post\",\"info_search_post\",\"planning_confidence_post\"]}
out[\"exploratory_bases\"]={k:{str(z):calc(x[(x.age_band==4)&(x.online_grocery_pre==1)&x.digital_confidence_pre.isin([4,5])&(x.assignment==z)],k)[0][\"pair\"] for z in [0,1]} for k in [\"awareness\",\"consideration\",\"usage\"]}
print(json.dumps(out))
